unsafe extern "C-unwind" fn swap_dst_buf(
    mut xd: *mut MACROBLOCKD,
    mut dst_bufs: *mut *const BUFFER_SET,
    mut num_planes: core::ffi::c_int,
) {
    let mut buf0: *const BUFFER_SET = *dst_bufs.offset(0 as core::ffi::c_int as isize);
    let fresh4 = &raw mut *dst_bufs.offset(0 as core::ffi::c_int as isize);
    *fresh4 = *dst_bufs.offset(1 as core::ffi::c_int as isize);
    let fresh5 = &raw mut *dst_bufs.offset(1 as core::ffi::c_int as isize);
    *fresh5 = buf0;
    restore_dst_buf(xd, **dst_bufs.offset(0 as core::ffi::c_int as isize), num_planes);
}
#[inline]
unsafe extern "C-unwind" fn get_rd_thresh_from_best_rd(
    mut ref_best_rd: int64_t,
    mut mul_factor: core::ffi::c_int,
    mut div_factor: core::ffi::c_int,
) -> int64_t {
    let mut rd_thresh: int64_t = ref_best_rd;
    if div_factor != 0 as core::ffi::c_int {
        rd_thresh = if ref_best_rd
            < div_factor as int64_t * (INT64_MAX as int64_t / mul_factor as int64_t)
        {
            ref_best_rd / div_factor as int64_t * mul_factor as int64_t
        } else {
            INT64_MAX as int64_t
        };
    }
    return rd_thresh;
}
