unsafe extern "C-unwind" fn av1_check_newmv_joint_nonzero(
    mut cm: *const AV1_COMMON,
    x: *mut MACROBLOCK,
) -> core::ffi::c_int {
    let mut xd: *mut MACROBLOCKD = &raw mut (*x).e_mbd;
    let mut mbmi: *mut MB_MODE_INFO = *((*xd).mi).offset(0 as core::ffi::c_int as isize);
    let this_mode: PREDICTION_MODE = (*mbmi).mode;
    if this_mode as core::ffi::c_int == NEW_NEWMV as core::ffi::c_int {
        let ref_mv_0: int_mv = av1_get_ref_mv(x, 0 as core::ffi::c_int) as int_mv;
        let ref_mv_1: int_mv = av1_get_ref_mv(x, 1 as core::ffi::c_int) as int_mv;
        if (*mbmi).mv[0 as core::ffi::c_int as usize].as_int == ref_mv_0.as_int
            || (*mbmi).mv[1 as core::ffi::c_int as usize].as_int == ref_mv_1.as_int
        {
            return 0 as core::ffi::c_int;
        }
    } else if this_mode as core::ffi::c_int == NEAREST_NEWMV as core::ffi::c_int
        || this_mode as core::ffi::c_int == NEAR_NEWMV as core::ffi::c_int
    {
        let ref_mv_1_0: int_mv = av1_get_ref_mv(x, 1 as core::ffi::c_int) as int_mv;
        if (*mbmi).mv[1 as core::ffi::c_int as usize].as_int == ref_mv_1_0.as_int {
            return 0 as core::ffi::c_int;
        }
    } else if this_mode as core::ffi::c_int == NEW_NEARESTMV as core::ffi::c_int
        || this_mode as core::ffi::c_int == NEW_NEARMV as core::ffi::c_int
    {
        let ref_mv_0_0: int_mv = av1_get_ref_mv(x, 0 as core::ffi::c_int) as int_mv;
        if (*mbmi).mv[0 as core::ffi::c_int as usize].as_int == ref_mv_0_0.as_int {
            return 0 as core::ffi::c_int;
        }
    } else if this_mode as core::ffi::c_int == NEWMV as core::ffi::c_int {
        let ref_mv_0_1: int_mv = av1_get_ref_mv(x, 0 as core::ffi::c_int) as int_mv;
        if (*mbmi).mv[0 as core::ffi::c_int as usize].as_int == ref_mv_0_1.as_int {
            return 0 as core::ffi::c_int;
        }
    }
    return 1 as core::ffi::c_int;
}
