unsafe extern "C-unwind" fn prune_ref(
    ref_frame: *const MV_REFERENCE_FRAME,
    ref_display_order_hint: *const core::ffi::c_uint,
    frame_display_order_hint: core::ffi::c_uint,
    mut ref_frame_list: *const core::ffi::c_int,
) -> core::ffi::c_int {
    let mut i: core::ffi::c_int = 0 as core::ffi::c_int;
    while i < 2 as core::ffi::c_int {
        if !(*ref_frame_list.offset(i as isize) == NONE_FRAME as core::ffi::c_int) {
            if *ref_frame.offset(0 as core::ffi::c_int as isize) as core::ffi::c_int
                == *ref_frame_list.offset(i as isize)
                || *ref_frame.offset(1 as core::ffi::c_int as isize) as core::ffi::c_int
                    == *ref_frame_list.offset(i as isize)
            {
                if av1_encoder_get_relative_dist(
                    *ref_display_order_hint
                        .offset(
                            (*ref_frame_list.offset(i as isize)
                                - LAST_FRAME as core::ffi::c_int) as isize,
                        ) as core::ffi::c_int,
                    frame_display_order_hint as core::ffi::c_int,
                ) < 0 as core::ffi::c_int
                {
                    return 1 as core::ffi::c_int;
                }
            }
        }
        i += 1;
    }
    return 0 as core::ffi::c_int;
}
