unsafe extern "C-unwind" fn has_closest_ref_frames(
    mut ref_frame: *const MV_REFERENCE_FRAME,
    mut closest_past_ref: int8_t,
    mut closest_future_ref: int8_t,
) -> core::ffi::c_int {
    let mut has_closest_past_ref: core::ffi::c_int = (*ref_frame
        .offset(0 as core::ffi::c_int as isize) as core::ffi::c_int
        == closest_past_ref as core::ffi::c_int
        || *ref_frame.offset(1 as core::ffi::c_int as isize) as core::ffi::c_int
            == closest_past_ref as core::ffi::c_int) as core::ffi::c_int;
    let mut has_closest_future_ref: core::ffi::c_int = (*ref_frame
        .offset(0 as core::ffi::c_int as isize) as core::ffi::c_int
        == closest_future_ref as core::ffi::c_int
        || *ref_frame.offset(1 as core::ffi::c_int as isize) as core::ffi::c_int
            == closest_future_ref as core::ffi::c_int) as core::ffi::c_int;
    return (has_closest_past_ref != 0 && has_closest_future_ref != 0)
        as core::ffi::c_int;
}
