    let mut xy_sum: int64_t = 0 as int64_t;
    let mut xz_sum: int64_t = 0 as int64_t;
    let mut x_firstrow: int64_t = 0 as int64_t;
    let mut x_finalrow: int64_t = 0 as int64_t;
    let mut x_firstcol: int64_t = 0 as int64_t;
    let mut x_finalcol: int64_t = 0 as int64_t;
    let mut x2_firstrow: int64_t = 0 as int64_t;
    let mut x2_finalrow: int64_t = 0 as int64_t;
    let mut x2_firstcol: int64_t = 0 as int64_t;
    let mut x2_finalcol: int64_t = 0 as int64_t;
    x_sum += *diff.offset(0 as core::ffi::c_int as isize) as int64_t;
    x2_sum
        += (*diff.offset(0 as core::ffi::c_int as isize) as core::ffi::c_int
            * *diff.offset(0 as core::ffi::c_int as isize) as core::ffi::c_int)
            as int64_t;
    x_firstrow += *diff.offset(0 as core::ffi::c_int as isize) as int64_t;
    x2_firstrow
        += (*diff.offset(0 as core::ffi::c_int as isize) as core::ffi::c_int
            * *diff.offset(0 as core::ffi::c_int as isize) as core::ffi::c_int)
            as int64_t;
