        x_firstrow += x as int64_t;
        x2_sum += (x as core::ffi::c_int * x as core::ffi::c_int) as int64_t;
        x2_firstrow += (x as core::ffi::c_int * x as core::ffi::c_int) as int64_t;
        xy_sum += (x as core::ffi::c_int * y as core::ffi::c_int) as int64_t;
