unsafe extern "C-unwind" fn get_sse(
    mut cpi: *const AV1_COMP,
    mut x: *const MACROBLOCK,
    mut sse_y: *mut int64_t,
) -> int64_t {
    let mut cm: *const AV1_COMMON = &(*cpi).common;
    let num_planes: core::ffi::c_int = av1_num_planes(cm) as core::ffi::c_int;
    let mut xd: *const MACROBLOCKD = &(*x).e_mbd;
    let mut mbmi: *const MB_MODE_INFO = *((*xd).mi)
        .offset(0 as core::ffi::c_int as isize);
    let mut total_sse: int64_t = 0 as int64_t;
    let mut plane: core::ffi::c_int = 0 as core::ffi::c_int;
    while plane < num_planes {
        if plane != 0 && !(*xd).is_chroma_ref {
            break;
        }
        let p: *const macroblock_plane = &*((*x).plane).as_ptr().offset(plane as isize)
            as *const macroblock_plane;
        let pd: *const macroblockd_plane = &*((*xd).plane)
            .as_ptr()
            .offset(plane as isize) as *const macroblockd_plane;
        let bs: BLOCK_SIZE = get_plane_block_size(
            (*mbmi).bsize,
            (*pd).subsampling_x,
            (*pd).subsampling_y,
        ) as BLOCK_SIZE;
        let mut sse: core::ffi::c_uint = 0;
        let mut bw: core::ffi::c_int = 0;
        let mut bh: core::ffi::c_int = 0;
        let block_width: core::ffi::c_int = block_size_wide[bs as usize]
            as core::ffi::c_int;
        let block_height: core::ffi::c_int = block_size_high[bs as usize]
            as core::ffi::c_int;
        get_visible_dimensions(
            x,
            plane,
            bs,
            0 as core::ffi::c_int,
            0 as core::ffi::c_int,
            block_width,
            block_height,
            (*cpi).do_border_pad,
            &raw mut bw,
            &raw mut bh,
        );
        sse = pixel_dist_visible_only(
            cpi,
            x,
            (*p).src.buf,
            (*p).src.stride,
            (*pd).dst.buf,
            (*pd).dst.stride,
            bs,
            block_height,
            block_width,
            bh,
            bw,
        );
        total_sse += sse as int64_t;
        if plane == 0 && !sse_y.is_null() {
            *sse_y = sse as int64_t;
        }
        plane += 1;
    }
    total_sse <<= 4 as core::ffi::c_int;
    return total_sse;
}
#[no_mangle]
pub unsafe extern "C-unwind" fn av1_block_error_c(
    mut coeff: *const tran_low_t,
    mut dqcoeff: *const tran_low_t,
    mut block_size: intptr_t,
    mut ssz: *mut int64_t,
) -> int64_t {
    let mut i: core::ffi::c_int = 0;
    let mut error: int64_t = 0 as int64_t;
    let mut sqcoeff: int64_t = 0 as int64_t;
    i = 0 as core::ffi::c_int;
    while (i as intptr_t) < block_size {
        let diff: core::ffi::c_int = *coeff.offset(i as isize)
            - *dqcoeff.offset(i as isize);
        error += (diff * diff) as int64_t;
        sqcoeff += (*coeff.offset(i as isize) * *coeff.offset(i as isize)) as int64_t;
        i += 1;
    }
    *ssz = sqcoeff;
    return error;
}
