        av1_single_motion_search(
            cpi,
            x,
            bsize,
            ref_idx,
            rate_mv,
            search_range,
            mode_info,
            &raw mut best_mv,
            args as *mut HandleInterModeArgs,
        );
        if best_mv.as_int == INVALID_MV as uint32_t {
            return INT64_MAX as int64_t;
        }
        (*((*args).single_newmv)
            .offset(
                ref_mv_idx as isize,
            ))[refs[0 as core::ffi::c_int as usize] as usize] = best_mv;
