unsafe extern "C-unwind" fn skip_nearest_near_mv_using_refmv_weight(
    x: *const MACROBLOCK,
    this_mode: PREDICTION_MODE,
    ref_frame_type: int8_t,
    mut best_mode: PREDICTION_MODE,
) -> core::ffi::c_int {
    if this_mode as core::ffi::c_int != NEARESTMV as core::ffi::c_int
        && this_mode as core::ffi::c_int != NEARMV as core::ffi::c_int
    {
        return 0 as core::ffi::c_int;
    }
    if is_inter_mode(best_mode) == 0 {
        return 0 as core::ffi::c_int;
    }
    let mut xd: *const MACROBLOCKD = &(*x).e_mbd;
    if !(*xd).left_available || !(*xd).up_available {
        return 0 as core::ffi::c_int;
    }
    let mbmi_ext: *const MB_MODE_INFO_EXT = &(*x).mbmi_ext;
    let ref_mv_weight: *const uint16_t = ((*mbmi_ext).weight[ref_frame_type as usize])
        .as_ptr();
    let ref_mv_count: core::ffi::c_int = if (3 as core::ffi::c_int)
        < (*mbmi_ext).ref_mv_count[ref_frame_type as usize] as core::ffi::c_int
    {
        3 as core::ffi::c_int
    } else {
        (*mbmi_ext).ref_mv_count[ref_frame_type as usize] as core::ffi::c_int
    };
    if ref_mv_count == 0 as core::ffi::c_int {
        return 0 as core::ffi::c_int;
    }
    if this_mode as core::ffi::c_int == NEARESTMV as core::ffi::c_int
        && *ref_mv_weight.offset(0 as core::ffi::c_int as isize) as core::ffi::c_int
            >= REF_CAT_LEVEL
    {
        return 0 as core::ffi::c_int;
    }
    let mut nearest_refmv_count: core::ffi::c_int = 0 as core::ffi::c_int;
    let mut ref_mv_idx: core::ffi::c_int = 0 as core::ffi::c_int;
    while ref_mv_idx < ref_mv_count {
        if *ref_mv_weight.offset(ref_mv_idx as isize) as core::ffi::c_int
            >= REF_CAT_LEVEL
        {
            nearest_refmv_count += 1;
        }
        ref_mv_idx += 1;
    }
    let prune_thresh: core::ffi::c_int = 1 as core::ffi::c_int
        + (ref_mv_count >= 2 as core::ffi::c_int) as core::ffi::c_int;
    if nearest_refmv_count < prune_thresh {
        return 1 as core::ffi::c_int;
    }
    return 0 as core::ffi::c_int;
}
