unsafe extern "C-unwind" fn prune_ref_mv_idx_search(
    mut ref_mv_idx: core::ffi::c_int,
    mut best_ref_mv_idx: core::ffi::c_int,
    mut save_mv: *mut [int_mv; 2],
    mut mbmi: *mut MB_MODE_INFO,
    mut pruning_factor: core::ffi::c_int,
) -> core::ffi::c_int {
    let mut i: core::ffi::c_int = 0;
    let is_comp_pred: core::ffi::c_int = has_second_ref(mbmi) as core::ffi::c_int;
    let thr: core::ffi::c_int = 1 as core::ffi::c_int + is_comp_pred
        << pruning_factor + 1 as core::ffi::c_int;
    if ref_mv_idx > 0 as core::ffi::c_int {
        let mut idx: core::ffi::c_int = 0 as core::ffi::c_int;
        while idx < ref_mv_idx {
            if !((*save_mv.offset(idx as isize))[0 as core::ffi::c_int as usize].as_int
                == INVALID_MV as uint32_t)
            {
                let mut mv_diff: core::ffi::c_int = 0 as core::ffi::c_int;
                i = 0 as core::ffi::c_int;
                while i < 1 as core::ffi::c_int + is_comp_pred {
                    mv_diff
                        += abs(
                            (*save_mv.offset(idx as isize))[i as usize].as_mv.row
                                as core::ffi::c_int
                                - (*mbmi).mv[i as usize].as_mv.row as core::ffi::c_int,
                        )
                            + abs(
                                (*save_mv.offset(idx as isize))[i as usize].as_mv.col
                                    as core::ffi::c_int
                                    - (*mbmi).mv[i as usize].as_mv.col as core::ffi::c_int,
                            );
                    i += 1;
                }
                if best_ref_mv_idx == -(1 as core::ffi::c_int) && mv_diff <= thr {
                    return 1 as core::ffi::c_int;
                }
            }
            idx += 1;
        }
    }
    if ref_mv_idx < MAX_REF_MV_SEARCH - 1 as core::ffi::c_int {
        i = 0 as core::ffi::c_int;
        while i < is_comp_pred + 1 as core::ffi::c_int {
            (*save_mv.offset(ref_mv_idx as isize))[i as usize].as_int = (*mbmi)
                .mv[i as usize]
                .as_int;
            i += 1;
        }
    }
    return 0 as core::ffi::c_int;
}
