        (*args).above_pred_buf[1 as core::ffi::c_int as usize] = ((*obmc_buffer)
            .above_pred)
            .offset((MAX_SB_SQUARE >> 1 as core::ffi::c_int) as isize);
        (*args).above_pred_buf[2 as core::ffi::c_int as usize] = ((*obmc_buffer)
            .above_pred)
            .offset(MAX_SB_SQUARE as isize);
        (*args).left_pred_buf[0 as core::ffi::c_int as usize] = (*obmc_buffer).left_pred;
        (*args).left_pred_buf[1 as core::ffi::c_int as usize] = ((*obmc_buffer)
            .left_pred)
            .offset((MAX_SB_SQUARE >> 1 as core::ffi::c_int) as isize);
        (*args).left_pred_buf[2 as core::ffi::c_int as usize] = ((*obmc_buffer)
            .left_pred)
            .offset(MAX_SB_SQUARE as isize);
