#[inline]
unsafe extern "C-unwind" fn update_search_state(
    mut cpi: *const AV1_COMP,
    mut search_state: *mut InterModeSearchState,
    mut best_rd_stats_dst: *mut RD_STATS,
    mut ctx: *mut PICK_MODE_CONTEXT,
    mut new_best_rd_stats: *const RD_STATS,
    mut new_best_rd_stats_y: *const RD_STATS,
    mut new_best_rd_stats_uv: *const RD_STATS,
    mut new_best_mode: THR_MODES,
    mut x: *const MACROBLOCK,
    mut txfm_search_done: core::ffi::c_int,
) {
    let mut xd: *const MACROBLOCKD = &(*x).e_mbd;
    let mut mbmi: *const MB_MODE_INFO = *((*xd).mi)
        .offset(0 as core::ffi::c_int as isize);
    let skip_ctx: core::ffi::c_int = av1_get_skip_txfm_context(xd) as core::ffi::c_int;
    let skip_txfm: core::ffi::c_int = ((*mbmi).skip_txfm as core::ffi::c_int != 0
        && is_mode_intra(av1_mode_defs[new_best_mode as usize].mode) == 0)
        as core::ffi::c_int;
    (*search_state).best_rd = (*new_best_rd_stats).rdcost;
    (*search_state).best_mode_index = new_best_mode;
    *best_rd_stats_dst = *new_best_rd_stats;
    (*search_state).best_mbmode = *mbmi;
    (*search_state).best_skip2 = skip_txfm;
    (*search_state).best_mode_skippable = (*new_best_rd_stats).skip_txfm
        as core::ffi::c_int;
    if txfm_search_done != 0 {
        let skip_rate: int32_t = (*x)
            .mode_costs
            .skip_txfm_cost[skip_ctx
            as usize][((*new_best_rd_stats).skip_txfm as core::ffi::c_int != 0
            || skip_txfm != 0) as core::ffi::c_int as usize];
        let scaled_skip_rate: int32_t = increase_motion_mode_rate(
            cpi,
            mbmi,
            skip_rate as core::ffi::c_int,
        ) as int32_t;
        (*search_state).best_rate_y = ((*new_best_rd_stats_y).rate as int32_t
            + scaled_skip_rate) as core::ffi::c_int;
        (*search_state).best_rate_uv = (*new_best_rd_stats_uv).rate;
    }
    (*search_state).best_y_rdcost = *new_best_rd_stats_y;
    memcpy(
        (*ctx).tx_type_map as *mut core::ffi::c_void,
        (*xd).tx_type_map as *const core::ffi::c_void,
        ((*ctx).num_4x4_blk as size_t)
            .wrapping_mul(::core::mem::size_of::<uint8_t>() as size_t),
    );
}
