        let mut rd_stats: RD_STATS = RD_STATS {
            rate: 0,
            zero_rate: 0,
            dist: 0,
            rdcost: 0,
            sse: 0,
            skip_txfm: 0,
        };
        let mut rd_stats_y: RD_STATS = RD_STATS {
            rate: 0,
            zero_rate: 0,
            dist: 0,
            rdcost: 0,
            sse: 0,
            skip_txfm: 0,
        };
        let mut rd_stats_uv: RD_STATS = RD_STATS {
            rate: 0,
            zero_rate: 0,
            dist: 0,
            rdcost: 0,
            sse: 0,
            skip_txfm: 0,
        };
        av1_init_rd_stats(&raw mut rd_stats);
        av1_init_rd_stats(&raw mut rd_stats_y);
        av1_init_rd_stats(&raw mut rd_stats_uv);
        let mut rate_mv: core::ffi::c_int = 0;
        rate_mv = (*best_motion_mode_cands).motion_mode_cand[cand as usize].rate_mv;
        (*args).skip_motion_mode = (*best_motion_mode_cands)
            .motion_mode_cand[cand as usize]
            .skip_motion_mode;
        *mbmi = (*best_motion_mode_cands).motion_mode_cand[cand as usize].mbmi;
        rd_stats.rate = (*best_motion_mode_cands)
            .motion_mode_cand[cand as usize]
            .rate2_nocoeff;
