            (*x).txfm_search_info.skip_txfm = 0 as uint8_t;
            let mut pd: *mut macroblockd_plane = ((*xd).plane).as_mut_ptr();
            let orig_dst: BUFFER_SET = {
                let mut init = BUFFER_SET {
                    plane: [
                        (*pd.offset(0 as core::ffi::c_int as isize)).dst.buf,
                        (*pd.offset(1 as core::ffi::c_int as isize)).dst.buf,
                        (*pd.offset(2 as core::ffi::c_int as isize)).dst.buf,
                    ],
                    stride: [
                        (*pd.offset(0 as core::ffi::c_int as isize)).dst.stride,
                        (*pd.offset(1 as core::ffi::c_int as isize)).dst.stride,
                        (*pd.offset(2 as core::ffi::c_int as isize)).dst.stride,
                    ],
                };
                init
            };
            set_ref_ptrs(
                cm,
                xd,
                (*mbmi).ref_frame[0 as core::ffi::c_int as usize],
                (*mbmi).ref_frame[1 as core::ffi::c_int as usize],
            );
            (*mbmi).motion_mode = 0 as MOTION_MODE;
            let is_comp_pred: core::ffi::c_int = ((*mbmi)
                .ref_frame[1 as core::ffi::c_int as usize] as core::ffi::c_int
                > INTRA_FRAME as core::ffi::c_int) as core::ffi::c_int;
