#[inline(always)]
unsafe extern "C-unwind" fn skip_inter_mode(
    mut cpi: *mut AV1_COMP,
    mut x: *mut MACROBLOCK,
    bsize: BLOCK_SIZE,
    mut ref_frame_rd: *mut int64_t,
    mut midx: core::ffi::c_int,
    mut args: *mut InterModeSFArgs,
    mut is_low_temp_var: core::ffi::c_int,
) -> core::ffi::c_int {
    let sf: *const SPEED_FEATURES = &raw mut (*cpi).sf;
    let xd: *mut MACROBLOCKD = &raw mut (*x).e_mbd;
    let mode_enum: THR_MODES = av1_default_mode_order[midx as usize];
    let mut mode_def: *const MODE_DEFINITION = &*core::ptr::addr_of!(av1_mode_defs).cast::<MODE_DEFINITION>()
        .offset(mode_enum as isize) as *const MODE_DEFINITION;
    let this_mode: PREDICTION_MODE = (*mode_def).mode;
    let mut ref_frames: *const MV_REFERENCE_FRAME = ((*mode_def).ref_frame).as_ptr();
    let ref_frame: MV_REFERENCE_FRAME = *ref_frames
        .offset(0 as core::ffi::c_int as isize);
    let second_ref_frame: MV_REFERENCE_FRAME = *ref_frames
        .offset(1 as core::ffi::c_int as isize);
    let comp_pred: core::ffi::c_int = (second_ref_frame as core::ffi::c_int
        > INTRA_FRAME as core::ffi::c_int) as core::ffi::c_int;
    if ref_frame as core::ffi::c_int == INTRA_FRAME as core::ffi::c_int {
        return 1 as core::ffi::c_int;
    }
    let update_type: FRAME_UPDATE_TYPE = get_frame_update_type(
        &raw mut (*(*cpi).ppi).gf_group,
        (*cpi).gf_frame_index as core::ffi::c_int,
    ) as FRAME_UPDATE_TYPE;
    if (*sf).inter_sf.skip_arf_compound != 0
        && update_type as core::ffi::c_int == ARF_UPDATE as core::ffi::c_int
        && comp_pred != 0
    {
        return 1 as core::ffi::c_int;
    }
    if is_low_temp_var != 0 && comp_pred == 0
        && ref_frame as core::ffi::c_int != LAST_FRAME as core::ffi::c_int
        && this_mode as core::ffi::c_int != NEARESTMV as core::ffi::c_int
    {
        return 1 as core::ffi::c_int;
    }
    if inter_mode_compatible_skip(cpi, x, bsize, this_mode, ref_frames) != 0 {
        return 1 as core::ffi::c_int;
    }
    let ret: core::ffi::c_int = inter_mode_search_order_independent_skip(
        cpi,
        x,
        (*args).mode_skip_mask,
        (*args).search_state,
        (*args).skip_ref_frame_mask,
        this_mode,
        ((*mode_def).ref_frame).as_ptr(),
    ) as core::ffi::c_int;
    if ret == 1 as core::ffi::c_int {
        return 1 as core::ffi::c_int;
    }
    *(*args).skip_motion_mode = (ret == 2 as core::ffi::c_int) as core::ffi::c_int;
    if (*sf).interp_sf.skip_interp_filter_search == 0
        && (*sf).inter_sf.prune_comp_search_by_single_result > 0 as core::ffi::c_int
        && comp_pred != 0 && (*args).reach_first_comp_mode == 0 as core::ffi::c_int
    {
        analyze_single_states(cpi, (*args).search_state);
        (*args).reach_first_comp_mode = 1 as core::ffi::c_int;
    }
    let mut mul_fact: core::ffi::c_int = if (*(*args).search_state).best_mode_skippable
        != 0
    {
        (*args).mode_thresh_mul_fact
    } else {
        (1 as core::ffi::c_int) << MODE_THRESH_QBITS
    };
    let mut mode_threshold: int64_t = (*(*args).search_state)
        .mode_threshold[mode_enum as usize] * mul_fact as int64_t >> MODE_THRESH_QBITS;
    if (*(*args).search_state).best_rd < mode_threshold {
        return 1 as core::ffi::c_int;
    }
    if (*sf).interp_sf.skip_interp_filter_search == 0
        && (*sf).inter_sf.prune_comp_search_by_single_result > 0 as core::ffi::c_int
        && comp_pred != 0
    {
        if compound_skip_by_single_states(
            cpi,
            (*args).search_state,
            this_mode,
            ref_frame,
            second_ref_frame,
            x,
        ) != 0
        {
            return 1 as core::ffi::c_int;
        }
    }
    if (*sf).inter_sf.prune_compound_using_single_ref != 0 && comp_pred != 0 {
        if (*args).prune_cpd_using_sr_stats_ready == 0
            && (*args).num_single_modes_processed
                == NUM_SINGLE_REF_MODES as core::ffi::c_int
        {
            find_top_ref(ref_frame_rd as *mut int64_t);
            (*args).prune_cpd_using_sr_stats_ready = 1 as core::ffi::c_int;
        }
        if (*args).prune_cpd_using_sr_stats_ready != 0
            && !in_single_ref_cutoff(
                ref_frame_rd as *mut int64_t,
                ref_frame,
                second_ref_frame,
            )
        {
            return 1 as core::ffi::c_int;
        }
    }
    if (*sf).inter_sf.skip_ext_comp_nearmv_mode != 0
        && (this_mode as core::ffi::c_int == NEW_NEARMV as core::ffi::c_int
            || this_mode as core::ffi::c_int == NEAR_NEWMV as core::ffi::c_int)
    {
        return 1 as core::ffi::c_int;
    }
    if (*sf).inter_sf.prune_ext_comp_using_neighbors != 0 && comp_pred != 0 {
        if compound_skip_using_neighbor_refs(
            xd,
            this_mode,
            ref_frames,
            (*sf).inter_sf.prune_ext_comp_using_neighbors,
        ) != 0
        {
            return 1 as core::ffi::c_int;
        }
    }
    if (*sf).inter_sf.prune_comp_using_best_single_mode_ref != 0 && comp_pred != 0 {
        if skip_compound_using_best_single_mode_ref(
            this_mode,
            ref_frames,
            ((*(*args).search_state).best_single_mode).as_mut_ptr(),
            (*sf).inter_sf.prune_comp_using_best_single_mode_ref,
        ) != 0
        {
            return 1 as core::ffi::c_int;
        }
    }
    if (*sf).inter_sf.prune_nearest_near_mv_using_refmv_weight != 0 && comp_pred == 0 {
        let ref_frame_type: int8_t = av1_ref_frame_type(ref_frames) as int8_t;
        if skip_nearest_near_mv_using_refmv_weight(
            x,
            this_mode,
            ref_frame_type,
            (*(*args).search_state).best_mbmode.mode,
        ) != 0
        {
            if (is_inter_mode((*(*args).search_state).best_mbmode.mode) == 0)
                as core::ffi::c_int as core::ffi::c_long != 0
            {
                crate::platform::assertion(
                    (::core::mem::transmute::<
                        [u8; 16],
                        [core::ffi::c_char; 16],
                    >(*b"skip_inter_mode\0"))
                        .as_ptr(),
                    b"rdopt.c\0" as *const u8 as *const core::ffi::c_char,
                    5314 as core::ffi::c_int,
                    b"is_inter_mode(args->search_state->best_mbmode.mode)\0" as *const u8
                        as *const core::ffi::c_char,
                );
            } else {};
            return 1 as core::ffi::c_int;
        }
    }
    if (*sf).rt_sf.prune_inter_modes_with_golden_ref != 0
        && ref_frame as core::ffi::c_int == GOLDEN_FRAME as core::ffi::c_int
        && comp_pred == 0
    {
        let subgop_size: core::ffi::c_int = if (*(*cpi).ppi).gf_group.size
            < 16 as core::ffi::c_int
        {
            (*(*cpi).ppi).gf_group.size
        } else {
            16 as core::ffi::c_int
        };
        if (*cpi).rc.frames_since_golden > subgop_size >> 2 as core::ffi::c_int
            && (*(*args).search_state)
                .best_mbmode
                .ref_frame[0 as core::ffi::c_int as usize] as core::ffi::c_int
                != GOLDEN_FRAME as core::ffi::c_int
        {
            if bsize as core::ffi::c_int > BLOCK_16X16 as core::ffi::c_int
                && this_mode as core::ffi::c_int == NEWMV as core::ffi::c_int
                || this_mode as core::ffi::c_int == NEARMV as core::ffi::c_int
            {
                return 1 as core::ffi::c_int;
            }
        }
    }
    return 0 as core::ffi::c_int;
}
