#[inline]
unsafe extern "C-unwind" fn init_top_tx_no_split_rd_for_inter_modes(
    mut x: *mut MACROBLOCK,
    mut prune_inter_tx_split_rd_eval_lvl: core::ffi::c_int,
) {
    if prune_inter_tx_split_rd_eval_lvl == 0 {
        return;
    }
    let mut i: core::ffi::c_int = 0 as core::ffi::c_int;
    while i < MAX_TX_BLOCKS_IN_MAX_SB {
        let mut j: core::ffi::c_int = 0 as core::ffi::c_int;
        while j < TOP_INTER_TX_NO_SPLIT_COUNT {
            (*x).top_inter_tx_no_split_rd[i as usize][j as usize] = INT64_MAX as int64_t;
            j += 1;
        }
        i += 1;
    }
}
#[inline]
unsafe extern "C-unwind" fn calculate_cost_from_tpl_data(
    mut cpi: *const AV1_COMP,
    mut x: *mut MACROBLOCK,
    mut bsize: BLOCK_SIZE,
    mut mi_row: core::ffi::c_int,
    mut mi_col: core::ffi::c_int,
    mut inter_cost: *mut int64_t,
    mut intra_cost: *mut int64_t,
) {
    let cm: *const AV1_COMMON = &(*cpi).common;
    let sb_size: BLOCK_SIZE = (*(*cm).seq_params).sb_size;
    let tpl_bsize_1d: core::ffi::c_int = (*(*cpi).ppi).tpl_data.tpl_bsize_1d
        as core::ffi::c_int;
    let len: core::ffi::c_int = block_size_wide[sb_size as usize] as core::ffi::c_int
        / tpl_bsize_1d
        * (block_size_high[sb_size as usize] as core::ffi::c_int / tpl_bsize_1d);
    let mut sb_enc: *mut SuperBlockEnc = &raw mut (*x).sb_enc;
    if (*sb_enc).tpl_data_count == len {
        let tpl_bsize: BLOCK_SIZE = convert_length_to_bsize(tpl_bsize_1d) as BLOCK_SIZE;
        let tpl_stride: core::ffi::c_int = (*sb_enc).tpl_stride;
        let tplw: core::ffi::c_int = mi_size_wide[tpl_bsize as usize]
            as core::ffi::c_int;
        let tplh: core::ffi::c_int = mi_size_high[tpl_bsize as usize]
            as core::ffi::c_int;
        let nw: core::ffi::c_int = mi_size_wide[bsize as usize] as core::ffi::c_int
            / tplw;
        let nh: core::ffi::c_int = mi_size_high[bsize as usize] as core::ffi::c_int
            / tplh;
        if nw >= 1 as core::ffi::c_int && nh >= 1 as core::ffi::c_int {
            let of_h: core::ffi::c_int = mi_row
                % mi_size_high[sb_size as usize] as core::ffi::c_int;
            let of_w: core::ffi::c_int = mi_col
                % mi_size_wide[sb_size as usize] as core::ffi::c_int;
            let start: core::ffi::c_int = of_h / tplh * tpl_stride + of_w / tplw;
            let mut k: core::ffi::c_int = 0 as core::ffi::c_int;
            while k < nh {
                let mut l: core::ffi::c_int = 0 as core::ffi::c_int;
                while l < nw {
                    *inter_cost
                        += (*sb_enc)
                            .tpl_inter_cost[(start + k * tpl_stride + l) as usize];
                    *intra_cost
                        += (*sb_enc)
                            .tpl_intra_cost[(start + k * tpl_stride + l) as usize];
                    l += 1;
                }
                k += 1;
            }
            *inter_cost /= (nw * nh) as int64_t;
            *intra_cost /= (nw * nh) as int64_t;
        }
    }
}
